```javascript
/**
 * Recursively merges user preference overrides into app defaults.
 * - Plain objects are merged key-by-key (deep merge).
 * - Arrays, class instances, functions, dates, etc. are treated as atomic
 *   values and replaced outright (not merged element-by-element).
 * - `undefined` values in overrides are ignored (they don't erase a default);
 *   use `null` explicitly if you want to null out a preference.
 * - Neither input is mutated; a new object is returned.
 *
 * @param {object} defaults - The app's default preferences.
 * @param {object} overrides - The user's override preferences.
 * @returns {object} A new object with overrides merged into defaults.
 */
function mergeUserPrefs(defaults, overrides) {
  return deepMerge(defaults, overrides);
}

function deepMerge(base, patch) {
  if (!isPlainObject(base) || !isPlainObject(patch)) {
    // If patch isn't a mergeable object, it wins outright (when defined).
    return patch === undefined ? base : patch;
  }

  const result = { ...base };

  for (const key of Object.keys(patch)) {
    const patchValue = patch[key];

    if (patchValue === undefined) {
      continue; // don't let explicit `undefined` clobber a default
    }

    const baseValue = base[key];

    if (isPlainObject(baseValue) && isPlainObject(patchValue)) {
      result[key] = deepMerge(baseValue, patchValue);
    } else {
      result[key] = patchValue;
    }
  }

  return result;
}

function isPlainObject(value) {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

module.exports = { mergeUserPrefs };
```

