    v !== null && typeof v === 'object' && !Array.isArray(v);

  const merge = (base, patch) => {
    const result = { ...base };
    for (const key of Object.keys(patch)) {
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') continue;
      const patchVal = patch[key];
      const baseVal = base[key];
