```javascript
/**
 * Merges user preference overrides into app defaults.
 * - Deep-merges plain objects (recursively).
 * - Arrays and non-plain-object values in `overrides` replace the default wholesale.
 * - `null`/`undefined` overrides are ignored (default is kept), so users can't
 *   accidentally blank out a setting by omission in a partial payload.
 * - Neither input is mutated; a new object tree is returned.
 */
function mergeUserPrefs(defaults, overrides) {
  const isPlainObject = (val) =>
    typeof val === 'object' &&
    val !== null &&
    !Array.isArray(val) &&
    Object.getPrototypeOf(val) === Object.prototype;

  if (!isPlainObject(defaults)) defaults = {};
  if (!isPlainObject(overrides)) return { ...defaults };

  const result = { ...defaults };

  for (const key of Object.keys(overrides)) {
    const overrideVal = overrides[key];
    const defaultVal = defaults[key];

    if (overrideVal === undefined || overrideVal === null) {
      // keep default; explicit null/undefined shouldn't erase a setting
      continue;
    }

    if (isPlainObject(overrideVal) && isPlainObject(defaultVal)) {
      result[key] = mergeUserPrefs(defaultVal, overrideVal);
    } else {
      result[key] = overrideVal;
    }
  }

  return result;
}

module.exports = { mergeUserPrefs };
```

**Example:**
