  theme: 'light',
  notifications: { email: true, sms: false, frequency: 'daily' },
  tags: ['default'],
};

const overrides = {
  theme: 'dark',
  notifications: { sms: true, frequency: null }, // null -> keeps 'daily'
  tags: ['work', 'urgent'], // arrays replace wholesale, not merged element-wise
};

mergeUserPrefs(defaults, overrides);
// => {
//   theme: 'dark',
//   notifications: { email: true, sms: true, frequency: 'daily' },
