```javascript
/**
 * Recursively merges user preference overrides into app defaults.
 * - Plain objects are merged key-by-key (deep merge).
 * - Arrays and primitives in `overrides` replace the corresponding value wholesale.
 * - `undefined` values in `overrides` are ignored (so callers can pass partial
 *   objects without accidentally clearing a default).
 * - `null` is treated as an explicit value and will overwrite the default.
 *
 * Neither input is mutated; a new object is returned.
 */
function mergeUserPrefs(defaults, overrides) {
  if (!isPlainObject(defaults) || !isPlainObject(overrides)) {
    return overrides === undefined ? defaults : overrides;
  }

  const result = { ...defaults };

  for (const key of Object.keys(overrides)) {
    const overrideValue = overrides[key];

    if (overrideValue === undefined) {
      continue;
    }

    const defaultValue = defaults[key];

    if (isPlainObject(defaultValue) && isPlainObject(overrideValue)) {
      result[key] = mergeUserPrefs(defaultValue, overrideValue);
    } else {
      result[key] = overrideValue;
    }
  }

  return result;
}

function isPlainObject(value) {
  return (
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    Object.getPrototypeOf(value) === Object.prototype
  );
}

module.exports = { mergeUserPrefs };
```

**Notes on the design choices:**

- **Deep merge for nested objects, replace for arrays.** Merging arrays element-by-element is rarely what you want for prefs (e.g. a `favoriteTags: []` override should replace the list, not splice into it), so arrays are treated as atomic values.
- **`undefined` is a no-op, `null` is a value.** This lets a partial overrides object (e.g. from a form that only submits changed fields) omit untouched keys without needing to delete them, while still letting a user explicitly reset a field to `null`.
- **Non-mutating.** Uses spread/new objects at each level rather than mutating `defaults`, so the original preference objects (which may be cached or shared) stay intact.
- **Guards against prototype-polluting shapes** by checking `Object.getPrototypeOf(value) === Object.prototype`, so class instances, `Date`, `Map`, etc. in either input are treated as opaque values rather than recursed into.

