/**
 * Fetch a URL, retrying on network errors or non-2xx responses.
 * Uses exponential backoff with jitter between attempts.
 *
 * @param {string} url
 * @param {object} [options]
 * @param {number} [options.retries=3]        Max retry attempts (not counting the first try)
 * @param {number} [options.baseDelayMs=300]   Base delay for exponential backoff
 * @param {number} [options.maxDelayMs=5000]   Cap on backoff delay
 * @param {number} [options.timeoutMs=10000]   Per-attempt timeout
 * @param {RequestInit} [options.fetchOptions] Options passed through to fetch()
 * @param {(status:number)=>boolean} [options.retryOn] Predicate to decide if an HTTP status should be retried
 * @returns {Promise<Response>}
 */
async function retryFetch(url, options = {}) {
  const {
    retries = 3,
    baseDelayMs = 300,
    maxDelayMs = 5000,
    timeoutMs = 10000,
    fetchOptions = {},
    retryOn = (status) => status === 429 || status >= 500,
  } = options;

  let lastError;

  for (let attempt = 0; attempt <= retries; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(url, {
        ...fetchOptions,
        signal: controller.signal,
      });

      if (response.ok || !retryOn(response.status)) {
        return response;
      }

      lastError = new Error(`Request failed with status ${response.status}`);
    } catch (err) {
      lastError = err;
    } finally {
      clearTimeout(timer);
    }

    const isLastAttempt = attempt === retries;
    if (isLastAttempt) break;

    const backoff = Math.min(maxDelayMs, baseDelayMs * 2 ** attempt);
    const jitter = Math.random() * backoff * 0.3;
    await new Promise((resolve) => setTimeout(resolve, backoff + jitter));
  }

  throw lastError;
}

module.exports = { retryFetch };
```

